class Solution {
public:
    int minKBitFlips(vector<int>& nums, int k) {
        int n = nums.size();
        int flips = 0;
        int cur_flipped = 0;
        for (int i = 0; i < n; ++i) {
            if (i >= k && nums[i - k] == 2) {
                cur_flipped ^= 1;
            }
            if ((nums[i] ^ cur_flipped) == 0) {
                if (i + k > n) return -1;
                nums[i] = 2;
                cur_flipped ^= 1;
                flips++;
            }
        }
        return flips;
    }
};

