var minKBitFlips = function(nums, k) {
    const n = nums.length;
    let flips = 0;
    let curFlipped = 0;
    for (let i = 0; i < n; i++) {
        if (i >= k && nums[i - k] === 2) {
            curFlipped ^= 1;
        }
        if ((nums[i] ^ curFlipped) === 0) {
            if (i + k > n) return -1;
            nums[i] = 2;
            curFlipped ^= 1;
            flips++;
        }
    }
    return flips;
};
